#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
vector<double> confidence={0.1,0.2,0.45,0.55,0.8,0.9};
vector<int> label={0,0,1,0,1,1};
double ece=0;
for(int bin=0;bin<3;bin++){
    double score=0,rate=0;int count=0;
    for(int i=0;i<int(confidence.size());i++)
        if(min(2,int(confidence[i]*3))==bin){
            score+=confidence[i];rate+=label[i];count++;
        }
    if(count>0)ece+=double(count)/confidence.size()*fabs(score/count-rate/count);
}
cout<<"Expected calibration error "<<ece<<endl;
    return 0;
}

