#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
vector<double> prediction={0.2,0.4,0.6,0.7,0.9};
vector<int> truth={0,1,0,1,1};
double falsePositiveCost=1,falseNegativeCost=4;
for(double threshold:{0.3,0.5,0.7}){
    double total=0;
    for(int i=0;i<int(prediction.size());i++){
        bool predicted=prediction[i]>=threshold;
        if(predicted&&!truth[i])total+=falsePositiveCost;
        if(!predicted&&truth[i])total+=falseNegativeCost;
    }
    cout<<"Threshold "<<threshold<<" cost "<<total<<endl;
}
    return 0;
}

